window.futvizVista("jugador-completo","<div class=\"rx-mount\" data-rx=\"venn\" data-rx-id=\"jugador-completo\" style=\"min-height:900px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"jugador-completo\"]={\"id\":\"jugador-completo\",\"titulo\":\"Jugador completo\",\"bajada\":\"El jugador que est\u00e1 en el top de su posici\u00f3n en tres cosas a la vez, y cu\u00e1ntos hay.\",\"pregunta\":\"\u00bfQui\u00e9n destaca a la vez en tres cosas de su puesto?\",\"tabla\":\"jugador-completo\",\"queMirar\":\"Muestra qui\u00e9n est\u00e1 entre los mejores de su posici\u00f3n en tres cosas a la vez. Cada c\u00edrculo agrupa a los jugadores que destacan en una de ellas, y quien cae en el centro destaca en las tres, mientras que las regiones de en medio son combinaciones de dos.\\nEl deslizador define qu\u00e9 tan exigente es \u00abentre los mejores\u00bb: es el porcentaje de arriba de su posici\u00f3n, de 5% a 25%, as\u00ed que con uno bajo solo entran los m\u00e1s destacados y con uno alto entra mucha m\u00e1s gente.\",\"fuente\":\"Understat y FBref\",\"venns\":[{\"id\":\"defensa\",\"tab\":\"Defensa completo\",\"pos\":\"Defensa\",\"plural\":\"defensas\",\"titulo\":\"El defensa completo\",\"sets\":[{\"nombre\":\"Defiende\",\"col\":\"rec\",\"def\":\"Entradas ganadas + intercepciones por 90'\"},{\"nombre\":\"Crea peligro\",\"col\":\"npxga\",\"def\":\"xG sin penales + xA por 90'\"},{\"nombre\":\"Participa\",\"col\":\"chain\",\"def\":\"xG de todas las jugadas en que interviene, por 90' (xGChain)\"}]},{\"id\":\"medio\",\"tab\":\"Medio completo\",\"pos\":\"Medio\",\"plural\":\"mediocampistas\",\"titulo\":\"El mediocampista completo\",\"sets\":[{\"nombre\":\"Defiende\",\"col\":\"rec\",\"def\":\"Entradas ganadas + intercepciones por 90'\"},{\"nombre\":\"Crea peligro\",\"col\":\"npxga\",\"def\":\"xG sin penales + xA por 90'\"},{\"nombre\":\"Construye\",\"col\":\"bld\",\"def\":\"xG de construcci\u00f3n por 90' (jugadas en que participa sin tirar ni asistir)\"}]},{\"id\":\"delantero\",\"tab\":\"Delantero completo\",\"pos\":\"Delantero\",\"plural\":\"delanteros\",\"titulo\":\"El delantero completo\",\"sets\":[{\"nombre\":\"Remata\",\"col\":\"npx\",\"def\":\"xG sin penales por 90'\"},{\"nombre\":\"Asiste\",\"col\":\"xa\",\"def\":\"xA por 90'\"},{\"nombre\":\"Se asocia\",\"col\":\"bld\",\"def\":\"xG de construcci\u00f3n por 90' (jugadas en que participa sin tirar ni asistir)\"}]}]};</script>");